# Edits here are overwritten by the next release — change the generator instead.
class ClaudeCodeSessionTracker < Formula
  desc "See every Claude Code session on your machine in a local dashboard"
  homepage "https://github.com/meyusufdemirci/claude-code-session-tracker"
  url "https://registry.npmjs.org/claude-code-session-tracker/-/claude-code-session-tracker-0.4.0.tgz"
  sha256 "f2367c43a6a23f38ee360abb44d7857fcbb12b43a19acb9c0abca7a399fad13b"
  license "MIT"

  depends_on "node"

  def install
    system "npm", "install", *std_npm_args
    bin.install_symlink Dir["#{libexec}/bin/*"]
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/claude-code-session-tracker --version")

    # A machine that has never run Claude Code is the state every install starts
    # in, and the answer to it is an empty list rather than an error.
    result = JSON.parse(shell_output("#{bin}/claude-code-session-tracker --json --claude-dir #{testpath}/claude"))
    assert_equal 0, result["total"]
    assert_empty result["sessions"]
  end
end
